{"content": "import json
v2   = json.load(open('files/input/FN2603200001-7501_v2_06e0934eeb94.json', encoding='utf-8'))
orig = json.load(open('files/input/FN2603200001-7501.json', encoding='utf-8'))

print('v2   line_item_count:', v2['line_item_count'])
print('orig line_item_count:', orig['line_item_count'])
print()

# Compare headers
h2 = v2['header']
ho = orig['header']
diff_keys = [k for k in ho if ho.get(k) != h2.get(k)]
if diff_keys:
    print('=== Header diffs ===')
    for k in diff_keys:
        print(f'  [{k}]')
        print(f'    orig: {repr(ho.get(k))}')
        print(f'    v2:   {repr(h2.get(k))}')
else:
    print('Headers identical')

print()
# Compare line items count & spot check
print(f'orig items: {len(orig["line_items"])}  v2 items: {len(v2["line_items"])}')
print()
for i, (o, n) in enumerate(zip(orig['line_items'], v2['line_items'])):
    diffs = {}
    for k in o:
        if o.get(k) != n.get(k):
            diffs[k] = (o.get(k), n.get(k))
    if diffs:
        print(f'--- item {i} (line_no orig={o["line_no"]} v2={n["line_no"]}) ---')
        for k, (ov, nv) in diffs.items():
            print(f'  [{k}] orig={repr(ov)}  v2={repr(nv)}')
